11	// tallyInput 构造本题回归保障使用的带委托转账提案：
12	// alice/bob/carol/dave 权重 400/200/100/300；bob、carol 委托给 alice，
13	// dave 不委托。因此两个最终代表归集票重：alice 400+200+100=700，
14	// dave 300，总权重 1000。窗口 [100,200)、时间锁 300、法定人数 600，
15	// 动作是一笔有效转账 transfer:grants:250。
16	func tallyInput(id string) *CreateVoteInput {
17		return &CreateVoteInput{
18			ID: id,
19			Members: []VoteMember{
20				{ID: "alice", Weight: 400},
21				{ID: "bob", Weight: 200},
22				{ID: "carol", Weight: 100},
23				{ID: "dave", Weight: 300},
24			},
25			Delegations: []Delegation{{From: "bob", To: "alice"}, {From: "carol", To: "alice"}},
26			Quorum:      600,
27			StartAt:     100,
28			Deadline:    200,
29			TimelockEnd: 300,
30			Actions:     []string{"transfer:grants:250"},
31		}
32	}
33	
34	// tallySetup 完成提案创建与两张窗口内票据：dave 在 130 投出归集 300 权重
35	// 反对票，alice 在 170 投出归集 700 权重赞成票。返回 store 与提案编号。
36	func tallySetup(t *testing.T, id string) (*Store, string) {
37		t.Helper()
38		store, path := openTempStore(t, 1000)
39		mustCreateVote(t, store, tallyInput(id))
40		if _, err := store.CastVote(id, "dave", false, 130); err != nil {
41			t.Fatalf("dave against ballot: %v", err)
42		}
43		if _, err := store.CastVote(id, "alice", true, 170); err != nil {
44			t.Fatalf("alice for ballot: %v", err)
45		}
46		return store, path
47	}
48	
49	// tallyExpectedMembers 返回提案创建时的完整成员/委托视图（保持创建顺序），
50	// 供保存失败后断言“成员、委托和动作内容不被失败尝试改写”。
51	func tallyExpectedMembers() map[string]MemberView {
52		return map[string]MemberView{
53			"alice": {ID: "alice", Weight: 400, Path: []string{"alice"}, Delegate: "alice", Direct: ""},
54			"bob":   {ID: "bob", Weight: 200, Path: []string{"bob", "alice"}, Delegate: "alice", Direct: "alice"},
55			"carol": {ID: "carol", Weight: 100, Path: []string{"carol", "alice"}, Delegate: "alice", Direct: "alice"},
56			"dave":  {ID: "dave", Weight: 300, Path: []string{"dave"}, Delegate: "dave", Direct: ""},
57		}
58	}
59	
60	// assertTallyUntouchedFunds 断言计票不执行动作、不动资金：资金库 1000、
61	// 没有任何收款账户余额、没有执行凭据。
62	func assertTallyUntouchedFunds(t *testing.T, store *Store) {
63		t.Helper()
64		if bal, err := store.TreasuryBalance(); err != nil || bal != 1000 {
65			t.Fatalf("treasury = %d err=%v, tally must not move funds, want 1000", bal, err)
66		}
67		if all, err := store.Balances(); err != nil || len(all) != 0 {
68			t.Fatalf("recipient balances = %v err=%v, tally must not credit recipients, want none", all, err)
69		}
70		if receipts, err := store.Receipts(); err != nil || len(receipts) != 0 {
71			t.Fatalf("receipts = %v err=%v, tally must not produce execution receipts, want none", receipts, err)
72		}
73	}
74	
75	// assertTallyBallotsPreserved 断言两张已保存票据的代表、权重、选择、首次
76	// 时间与顺序全部保留：dave 反对 300@130 在前，alice 赞成 700@170 在后。
77	func assertTallyBallotsPreserved(t *testing.T, v *VoteProposalView) {
78		t.Helper()
79		if len(v.Ballots) != 2 {
80			t.Fatalf("ballots = %+v, want exactly the two saved ballots", v.Ballots)
81		}
82		first, second := v.Ballots[0], v.Ballots[1]
83		if first.Representative != "dave" || first.Weight != 300 || first.Support || first.VotedAt != 130 {
84			t.Fatalf("first ballot = %+v, want dave against weight=300 voted_at=130", first)
85		}
86		if second.Representative != "alice" || second.Weight != 700 || !second.Support || second.VotedAt != 170 {
87			t.Fatalf("second ballot = %+v, want alice for weight=700 voted_at=170", second)
88		}
89	}
90	
91	// assertTallyProposalShape 断言提案的窗口、时间锁、法定人数、总权重、动作
92	// 原文以及成员/委托内容仍是创建时的样子，不被任何保存失败改写。
93	func assertTallyProposalShape(t *testing.T, v *VoteProposalView) {
94		t.Helper()
95		if v.Quorum != 600 || v.StartAt != 100 || v.Deadline != 200 ||
96			v.TimelockEnd != 300 || v.TotalWeight != 1000 {
97			t.Fatalf("proposal parameters changed: %+v", v)
98		}
99		if !sameActions(v.Actions, []string{"transfer:grants:250"}) {
100			t.Fatalf("actions = %v, want original transfer action text", v.Actions)
101		}
102		assertMemberViews(t, "after tally save failure", memberPaths(v), tallyExpectedMembers())
103	}
104	
105	// TestTallyFirstCountBaseline：正常在截止时刻 200 首次计票的基线：
106	// 赞成 700、反对 300、参与 1000，达到法定人数 600 且赞成严格多于反对 => 通过，
107	// 首次计票时间为 200；计票只确定状态，不执行转账，资金库、收款账户余额与
108	// 执行凭据保持原样。这是两类保存失败场景共同的对照。
109	func TestTallyFirstCountBaseline(t *testing.T) {
110		store, _ := tallySetup(t, "gip-tally-ok")
111		defer store.Close()
112	
113		res, err := store.TallyVote("gip-tally-ok", 200)
114		if err != nil {
115			t.Fatalf("first tally at deadline: %v", err)
116		}
117		if !res.Passed || res.ForWeight != 700 || res.AgainstWeight != 300 ||
118			res.Turnout != 1000 || res.Quorum != 600 || res.TalliedAt != 200 {
119			t.Fatalf("tally = %+v, want passed for=700 against=300 turnout=1000 tallied_at=200", res)
120		}
121	
122		v, ok, err := store.VoteProposal("gip-tally-ok")
123		if err != nil || !ok {
124			t.Fatalf("query after tally: ok=%v err=%v", ok, err)
125		}
126		if v.State != "passed" || v.Tally == nil {
127			t.Fatalf("state=%s tally=%+v, want passed with first conclusion", v.State, v.Tally)
128		}
129		if !v.Tally.Passed || v.Tally.ForWeight != 700 || v.Tally.AgainstWeight != 300 ||
130			v.Tally.Turnout != 1000 || v.Tally.Quorum != 600 || v.Tally.TalliedAt != 200 {
131			t.Fatalf("queried tally = %+v, want the 200 passed conclusion", v.Tally)
132		}
133		assertTallyBallotsPreserved(t, v)
134		assertTallyProposalShape(t, v)
135		assertTallyUntouchedFunds(t, store)
136	
137		// 再次计票（即使传入更晚的 210）始终返回首次 200 结论，不重新计票、
138		// 不改变首次时间，也不执行动作。
139		again, err := store.TallyVote("gip-tally-ok", 210)
140		if err != nil {
141			t.Fatalf("repeat tally: %v", err)
142		}
143		if !again.Passed || again.ForWeight != 700 || again.AgainstWeight != 300 ||
144			again.Turnout != 1000 || again.TalliedAt != 200 {
145			t.Fatalf("repeat tally = %+v, want the first 200 conclusion", again)
146		}
147		assertTallyUntouchedFunds(t, store)
148	}
149	
150	// TestTallyPreReplaceFailureLeavesNoConclusion：首次计票的保存失败发生在
151	// 状态文件替换之前（目录不可写，临时文件都无法创建）时，TallyVote 必须：
152	//   - 返回 nil 计票结果与具体保存原因，错误不能被识别成
153	//     ErrDurabilityUnconfirmed（这是“尚未写入”，不是“已写入但持久性未确认”）；
154	//   - 随后查询仍看到 voting 状态、没有计票结论；已保存票据的代表、权重、
155	//     选择、首次时间及顺序全部保留，成员、委托与动作内容不变；
156	//   - 保存条件恢复后在 210 再次计票才形成首次成功结论，首次计票时间为 210，
157	//     不沿用失败尝试的 200，也不因先前已经算出通过而跳过保存。
158	func TestTallyPreReplaceFailureLeavesNoConclusion(t *testing.T) {
159		store, path := tallySetup(t, "gip-tally-pre-replace")
160		defer store.Close()
161		const id = "gip-tally-pre-replace"
162	
163		// 记录失败前的完整状态文件字节：保存失败后它必须原样保留。
164		before, err := os.ReadFile(path)
165		if err != nil {
166			t.Fatal(err)
167		}
168	
169		// 目录不可写：提交在状态文件替换之前（创建临时文件）失败。
170		makeDirUnwritable(t, path)
171		res, err := store.TallyVote(id, 200)
172		if err == nil {
173			t.Fatal("expected save failure, got nil error")
174		}
175		// 返回的是具体保存原因，而不是成功结论、计票业务拒绝或“已写入”告警。
176		if res != nil {
177			t.Fatalf("pre-replacement failure must not return a tally result: %+v", res)
178		}
179		if errors.Is(err, ErrDurabilityUnconfirmed) {
180			t.Fatalf("pre-replacement failure must not be reported as durability warning: %v", err)
181		}
182		if errors.Is(err, ErrTallyRejected) {
183			t.Fatalf("a deadline-reached tally must not be rejected as a business rule: %v", err)
184		}
185		if !strings.Contains(err.Error(), "permission denied") {
186			t.Fatalf("error must carry the concrete save cause, got %v", err)
187		}
188	
189		// 保存失败后不能遗留临时文件或部分文件。
190		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".govflow-state-*")); len(leftovers) != 0 {
191			t.Fatalf("failed commit left temporary file(s): %v", leftovers)
192		}
193	
194		// 即使目录仍不可写，只读查询看到的也是失败前的完整状态：voting、无结论。
195		v, ok, qerr := store.VoteProposal(id)
196		if qerr != nil || !ok {
197			t.Fatalf("query after failed save: ok=%v err=%v", ok, qerr)
198		}
199		if v.State != "voting" || v.Tally != nil {
200			t.Fatalf("state=%s tally=%+v, want voting with no tally conclusion", v.State, v.Tally)
201		}
202		assertTallyBallotsPreserved(t, v)
203		assertTallyProposalShape(t, v)
204		assertTallyUntouchedFunds(t, store)
205	
206		// 原状态文件保留失败前的完整内容（字节一致）。
207		if after, rerr := os.ReadFile(path); rerr != nil || string(after) != string(before) {
208			t.Fatalf("state file changed despite pre-replacement save failure")
209		}
210	
211		// 恢复保存条件，并以新进程视角重开：读到的仍是 voting、两张原票据。
212		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
213			t.Fatalf("restore dir: %v", err)
214		}
215		if err := store.Close(); err != nil {
216			t.Fatalf("close: %v", err)
217		}
218		reopened, err := Open(path)
219		if err != nil {
220			t.Fatalf("reopen after failed tally: %v", err)
221		}
222		defer reopened.Close()
223		rv, ok, err := reopened.VoteProposal(id)
224		if err != nil || !ok {
225			t.Fatalf("query after reopen: ok=%v err=%v", ok, err)
226		}
227		if rv.State != "voting" || rv.Tally != nil {
228			t.Fatalf("after reopen state=%s tally=%+v, want voting with no conclusion", rv.State, rv.Tally)
229		}
230		assertTallyBallotsPreserved(t, rv)
231		assertTallyProposalShape(t, rv)
232	
233		// 210 再次计票才形成首次成功结论：通过、700/300/1000，首次计票时间是 210，
234		// 绝不沿用失败尝试的 200；它必须真正落盘（先前内存里已经算出通过，不能
235		// 因此跳过保存或把这次调用当成“已有结论”的重试）。
236		res210, err := reopened.TallyVote(id, 210)
237		if err != nil {
238			t.Fatalf("first successful tally after recovery at 210: %v", err)
239		}
240		if !res210.Passed || res210.ForWeight != 700 || res210.AgainstWeight != 300 ||
241			res210.Turnout != 1000 || res210.Quorum != 600 || res210.TalliedAt != 210 {
242			t.Fatalf("tally at 210 = %+v, want passed for=700 against=300 turnout=1000 tallied_at=210", res210)
243		}
244		sv, ok, err := reopened.VoteProposal(id)
245		if err != nil || !ok {
246			t.Fatalf("query after 210 tally: ok=%v err=%v", ok, err)
247		}
248		if sv.State != "passed" || sv.Tally == nil || !sv.Tally.Passed ||
249			sv.Tally.ForWeight != 700 || sv.Tally.AgainstWeight != 300 ||
250			sv.Tally.Turnout != 1000 || sv.Tally.TalliedAt != 210 {
251			t.Fatalf("after 210 tally state=%s tally=%+v, want passed with tallied_at=210", sv.State, sv.Tally)
252		}
253		assertTallyBallotsPreserved(t, sv)
254		assertTallyProposalShape(t, sv)
255		assertTallyUntouchedFunds(t, reopened)
256	
257		// 再次计票返回 210 的首次结论，不随新时间改变。
258		again, err := reopened.TallyVote(id, 300)
259		if err != nil {
260			t.Fatalf("repeat tally after success: %v", err)
261		}
262		if !again.Passed || again.TalliedAt != 210 || again.ForWeight != 700 || again.AgainstWeight != 300 {
263			t.Fatalf("repeat tally = %+v, want first successful 210 conclusion", again)
264		}
265	}
266	
267	// assertNoTallyLeftovers 断言没有计票提交遗留的临时状态文件。
268	func assertNoTallyLeftovers(t *testing.T, path string) {
269		t.Helper()
270		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".govflow-state-*")); len(leftovers) != 0 {
271			t.Fatalf("failed commit left temporary file(s): %v", leftovers)
272		}
273	}
274	
275	// TestTallyDirSyncFailureWrittenButUnconfirmed：首次计票时状态文件已替换
276	// 成功、只在之后的目录同步失败（目录可写可进入但不可读，0o300）时，
277	// TallyVote 必须：
278	//   - 仍没有成功计票结果返回（nil），但错误能识别为
279	//     ErrDurabilityUnconfirmed（*DurabilityError），并保留具体失败原因；
280	//   - 查询应看到 passed 状态与 200 的首次结论——首次结论、计票时间与提案
281	//     状态其实已一起写入；票据与资金记录仍保持一致；
282	//   - 保存条件恢复后在 210 再次计票，应返回已经写入的 200 结论，而不是
283	//     重新算一个 210，也不报错。
284	func TestTallyDirSyncFailureWrittenButUnconfirmed(t *testing.T) {
285		store, path := tallySetup(t, "gip-tally-dirsync")
286		const id = "gip-tally-dirsync"
287		defer store.Close()
288	
289		makeDirSyncFail(t, path)
290		res, err := store.TallyVote(id, 200)
291		if err == nil {
292			t.Fatal("expected durability warning error, got nil")
293		}
294		// 调用本身没有成功计票结果：结论已落盘，但这次写入的持久性未确认。
295		if res != nil {
296			t.Fatalf("durability-uncertain call must not report a successful result: %+v", res)
297		}
298		if !errors.Is(err, ErrDurabilityUnconfirmed) {
299			t.Fatalf("err = %v, want errors.Is ErrDurabilityUnconfirmed", err)
300		}
301		var derr *DurabilityError
302		if !errors.As(err, &derr) || derr.Cause == nil {
303			t.Fatalf("err = %v (%T), want *DurabilityError with concrete cause", err, err)
304		}
305		if !strings.Contains(err.Error(), derr.Cause.Error()) {
306			t.Fatalf("err %q must preserve the underlying save failure %q", err, derr.Cause)
307		}
308		assertNoTallyLeftovers(t, path)
309	
310		// 恢复目录后查询：passed 状态与 200 的首次结论已写入，票据保持一致。
311		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
312			t.Fatalf("restore dir: %v", err)
313		}
314		v, ok, qerr := store.VoteProposal(id)
315		if qerr != nil || !ok {
316			t.Fatalf("query after durability warning: ok=%v err=%v", ok, qerr)
317		}
318		if v.State != "passed" || v.Tally == nil {
319			t.Fatalf("state=%s tally=%+v, want passed with the written 200 conclusion", v.State, v.Tally)
320		}
321		if !v.Tally.Passed || v.Tally.ForWeight != 700 || v.Tally.AgainstWeight != 300 ||
322			v.Tally.Turnout != 1000 || v.Tally.Quorum != 600 || v.Tally.TalliedAt != 200 {
323			t.Fatalf("written tally = %+v, want passed for=700 against=300 turnout=1000 tallied_at=200", v.Tally)
324		}
325		assertTallyBallotsPreserved(t, v)
326		assertTallyProposalShape(t, v)
327		assertTallyUntouchedFunds(t, store)
328	
329		// 以全新进程视角重开，写入的结论必须能跨进程读到，且通过严格重放校验。
330		if err := store.Close(); err != nil {
331			t.Fatalf("close: %v", err)
332		}
333		reopened, err := Open(path)
334		if err != nil {
335			t.Fatalf("reopen after durability-uncertain tally: %v", err)
336		}
337		defer reopened.Close()
338		rv, ok, err := reopened.VoteProposal(id)
339		if err != nil || !ok {
340			t.Fatalf("query after reopen: ok=%v err=%v", ok, err)
341		}
342		if rv.State != "passed" || rv.Tally == nil || !rv.Tally.Passed || rv.Tally.TalliedAt != 200 {
343			t.Fatalf("after reopen state=%s tally=%+v, want passed with tallied_at=200", rv.State, rv.Tally)
344		}
345		assertTallyBallotsPreserved(t, rv)
346	
347		// 210 再次计票：返回已经写入的 200 结论，不重新计票、不改首次时间。
348		again, err := reopened.TallyVote(id, 210)
349		if err != nil {
350			t.Fatalf("repeat tally after recovery: %v", err)
351		}
352		if !again.Passed || again.ForWeight != 700 || again.AgainstWeight != 300 ||
353			again.Turnout != 1000 || again.Quorum != 600 || again.TalliedAt != 200 {
354			t.Fatalf("repeat tally = %+v, want the already-written 200 conclusion", again)
355		}
356		// 查询结论与首次结论一致，资金仍未被计票触动。
357		fv, _, err := reopened.VoteProposal(id)
358		if err != nil {
359			t.Fatal(err)
360		}
361		if fv.State != "passed" || fv.Tally == nil || fv.Tally.TalliedAt != 200 {
362			t.Fatalf("state=%s tally=%+v, want passed tallied_at=200", fv.State, fv.Tally)
363		}
364		assertTallyUntouchedFunds(t, reopened)
365	}
